import pandas as pd
import numpy as np

# Load the data
df = pd.read_csv('chunks_csv/changespillover/changespillover_2022_2023_ghg.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Ensure the data is in the correct format
df = df.set_index('borough')
adjacency = adjacency.set_index('borough')

# Calculate change in GHG between 2022 and 2023
df['change'] = df['GHG_2023'] - df['GHG_2022']

# Identify neighbor boroughs for each borough
neighbor_boroughs = {}
for index, row in adjacency.iterrows():
    if index not in neighbor_boroughs:
        neighbor_boroughs[index] = []
    neighbor_boroughs[index].append(row['neighbor'])

# Compute similarity in change for each borough
similarity = {}
for index, row in df.iterrows():
    similarity[index] = []
    for neighbor in neighbor_boroughs[index]:
        if neighbor in df.index:
            similarity[index].append(df.loc[neighbor, 'change'])
        else:
            similarity[index].append(0)

# Compute Moran's I statistic
n = len(df)
W = 0
S = 0
for index, row in df.iterrows():
    for neighbor in neighbor_boroughs[index]:
        if neighbor in df.index:
            W += 1
            S += row['change'] * df.loc[neighbor, 'change']
    if len(similarity[index]) > 0:
        S /= len(similarity[index])

S_bar = (n * (n - 1) * np.mean(df['change'])**2) / (n * (n - 1) - 1)
W_bar = (n * (n - 1)) / (n * (n - 1) - 1)
Morans_I = (n * (n - 1) * S - W * S_bar) / (W * W_bar * S_bar)

# Permutation test
p_value = 0
num_permutations = 500
for _ in range(num_permutations):
    # Shuffle the changes in GHG among the boroughs
    shuffled_changes = df['change'].sample(frac=1).values
    shuffled_df = df.copy()
    shuffled_df['change'] = shuffled_changes
    shuffled_similarity = {}
    for index, row in df.iterrows():
        shuffled_similarity[index] = []
        for neighbor in neighbor_boroughs[index]:
            if neighbor in df.index:
                shuffled_similarity[index].append(shuffled_df.loc[neighbor, 'change'])
            else:
                shuffled_similarity[index].append(0)
    shuffled_S = 0
    for index, row in shuffled_df.iterrows():
        for neighbor in neighbor_boroughs[index]:
            if neighbor in shuffled_df.index:
                shuffled_S += row['change'] * shuffled_df.loc[neighbor, 'change']
        if len(shuffled_similarity[index]) > 0:
            shuffled_S /= len(shuffled_similarity[index])
    shuffled_S_bar = (n * (n - 1) * np.mean(shuffled_df['change'])**2) / (n * (n - 1) - 1)
    shuffled_W_bar = (n * (n - 1)) / (n * (n - 1) - 1)
    shuffled_Morans_I = (n * (n - 1) * shuffled_S - (sum([len(neighbor_boroughs[index]) for index in df.index]) * shuffled_S_bar)) / ((sum([len(neighbor_boroughs[index]) for index in df.index]) * shuffled_W_bar * shuffled_S_bar))
    p_value += (Morans_I - shuffled_Morans_I) > 0

p_value /= num_permutations

data_points_used = len(df)
if p_value < 0.05:
    print(f'FINAL ANSWER: CLUSTERED (test statistic = {Morans_I}, p = {p_value})')
else:
    print(f'FINAL ANSWER: NOT CLUSTERED (test statistic = {Morans_I}, p = {p_value})')
